package fieldservice

import (
	"strconv"
	"strings"

	capabilities "example.com/m2-fieldservice/generated/capabilities"
)

func reject(code string) error {
	return &capabilities.BusinessError{Code: code}
}

func parseMoney(value string) (int64, bool) {
	if value == "" {
		return 0, false
	}

	negative := false
	if value[0] == '-' {
		negative = true
		value = value[1:]
	}
	if value == "" || strings.HasPrefix(value, "+") {
		return 0, false
	}

	parts := strings.Split(value, ".")
	if len(parts) > 2 || parts[0] == "" || len(parts) == 2 && len(parts[1]) > 2 {
		return 0, false
	}
	for _, part := range parts {
		if part == "" {
			continue
		}
		for _, character := range part {
			if character < '0' || character > '9' {
				return 0, false
			}
		}
	}

	whole, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil || whole > (int64(^uint64(0)>>1)-99)/100 {
		return 0, false
	}
	fraction := int64(0)
	if len(parts) == 2 {
		fractionText := parts[1]
		if len(fractionText) == 1 {
			fractionText += "0"
		}
		if fractionText != "" {
			fraction, err = strconv.ParseInt(fractionText, 10, 64)
			if err != nil {
				return 0, false
			}
		}
	}

	cents := whole*100 + fraction
	if negative {
		cents = -cents
	}
	return cents, true
}

func formatMoney(cents int64) string {
	sign := ""
	if cents < 0 {
		sign = "-"
		cents = -cents
	}
	return sign + strconv.FormatInt(cents/100, 10) + "." +
		leftPadTwo(strconv.FormatInt(cents%100, 10))
}

func leftPadTwo(value string) string {
	if len(value) == 1 {
		return "0" + value
	}
	return value
}
