// This file is initial project-owned business source. Domainry will never overwrite it.
package fieldservice

import (
	"context"
	"encoding/json"
	"strconv"

	capabilities "example.com/m2-fieldservice/generated/capabilities"
	"example.com/m2-fieldservice/generated/data"
	"example.com/m2-fieldservice/generated/schema"
)

type repairUsageLine struct {
	SparePartID string `json:"spare_part_id"`
	Quantity    int64  `json:"quantity"`
}

// CompleteRepair implements the project-owned service_request.complete_repair Handler.
func CompleteRepair(ctx context.Context, caps capabilities.CompleteRepairCapabilities, input capabilities.CompleteRepairInput) (capabilities.CompleteRepairOutput, error) {
	principal := caps.Execution.Principal()
	quoteCents, quoteValid := parseMoney(string(input.QuoteAmount))
	if !principal.Known || principal.UserID == "" || input.RequestID == "" || !quoteValid || quoteCents < 0 {
		return capabilities.CompleteRepairOutput{}, reject("validation.invalid_request")
	}

	var lines []repairUsageLine
	if err := json.Unmarshal([]byte(input.UsageLinesJson), &lines); err != nil || len(lines) == 0 {
		return capabilities.CompleteRepairOutput{}, reject("validation.invalid_usage_lines")
	}
	partIDs := make([]schema.SparePartID, 0, len(lines))
	quantities := make(map[schema.SparePartID]int64, len(lines))
	for _, line := range lines {
		partID := schema.SparePartID(line.SparePartID)
		if partID == "" || line.Quantity <= 0 {
			return capabilities.CompleteRepairOutput{}, reject("validation.invalid_usage_lines")
		}
		if _, duplicate := quantities[partID]; duplicate {
			return capabilities.CompleteRepairOutput{}, reject("validation.duplicate_spare_part")
		}
		quantities[partID] = line.Quantity
		partIDs = append(partIDs, partID)
	}

	targetID := caps.Execution.TargetID()
	request, err := caps.ServiceRequest.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	assigned := schema.NewServiceRequestAssignedUserIDReference(schema.IdentityUserID(principal.UserID))
	if request.Status != schema.ServiceRequestStatus("in_repair") {
		return capabilities.CompleteRepairOutput{}, reject("state.conflict")
	}
	if request.AssignedUserID == nil || request.AssignedUserID.ID() != assigned.ID() {
		return capabilities.CompleteRepairOutput{}, reject("authorization.forbidden")
	}

	parts, err := caps.SparePart.GetForUpdateBatch(ctx, partIDs)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	if len(parts) != len(partIDs) {
		return capabilities.CompleteRepairOutput{}, reject("validation.invalid_spare_part")
	}
	partsByID := make(map[schema.SparePartID]schema.SparePart, len(parts))
	for _, part := range parts {
		partsByID[part.ID] = part
	}

	stockMutations := make([]data.SparePartUpdateMutation, 0, len(lines))
	usageInputs := make([]schema.CreatePartUsage, 0, len(lines))
	for _, line := range lines {
		partID := schema.SparePartID(line.SparePartID)
		part, found := partsByID[partID]
		if !found {
			return capabilities.CompleteRepairOutput{}, reject("validation.invalid_spare_part")
		}
		if part.StockQuantity < line.Quantity {
			return capabilities.CompleteRepairOutput{}, reject("inventory.insufficient_stock")
		}
		unitPriceCents, valid := parseMoney(string(part.UnitPrice))
		if !valid || unitPriceCents < 0 || unitPriceCents != 0 && line.Quantity > int64(^uint64(0)>>1)/unitPriceCents {
			return capabilities.CompleteRepairOutput{}, reject("validation.invalid_part_price")
		}
		amount := formatMoney(unitPriceCents * line.Quantity)
		trace := "quantity=" + strconv.FormatInt(line.Quantity, 10) +
			";unit_price_snapshot=" + formatMoney(unitPriceCents) + ";amount=" + amount
		usage := schema.CreatePartUsage{
			Amount:                schema.PartUsageAmount(amount),
			CalculationTrace:      trace,
			OccurredAt:            input.CompletedAt,
			PerformedByUserID:     &principal.UserID,
			Quantity:              line.Quantity,
			ServiceRequestID:      schema.NewPartUsageServiceRequestIDReference(targetID),
			SparePartID:           schema.NewPartUsageSparePartIDReference(partID),
			UnitPriceSnapshot:     schema.PartUsageUnitPriceSnapshot(formatMoney(unitPriceCents)),
			OwnerDepartmentID:   request.OwnerDepartmentID,
			OwnerDepartmentPath: request.OwnerDepartmentPath,
		}
		usageInputs = append(usageInputs, usage)
		stockMutations = append(stockMutations, data.NewSparePartUpdate(partID).
			WithExpectedUpdatedAt(part.UpdatedAt).
			RequireStockQuantityAtLeast(line.Quantity, "inventory.insufficient_stock").
			SetStockQuantity(part.StockQuantity-line.Quantity))
	}

	if _, err = caps.SparePart.ConditionalUpdateBatch(ctx, stockMutations); err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	createdUsages, err := caps.PartUsage.CreateBatch(ctx, usageInputs)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}

	inputSnapshotBytes, err := json.Marshal(struct {
		QuoteAmount string `json:"quote_amount"`
		UsageCount  int    `json:"usage_count"`
	}{QuoteAmount: formatMoney(quoteCents), UsageCount: len(createdUsages)})
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	ledger, err := caps.FeeLedger.Create(ctx, schema.CreateFeeLedger{
		Amount:             schema.FeeLedgerAmount(formatMoney(quoteCents)),
		CalculationTrace:   "charge=quote_amount",
		InputSnapshot:      string(inputSnapshotBytes),
		Kind:               schema.FeeLedgerKind("charge"),
		LineageKey:         "service_request.charge:" + string(targetID),
		OccurredAt:         input.CompletedAt,
		PolicySnapshot:     `{"policy":"repair_completion","version":1}`,
		ServiceRequestID: schema.NewFeeLedgerServiceRequestIDReference(targetID),
	})
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}

	requestMutation := data.NewServiceRequestUpdate(targetID).
		WithExpectedUpdatedAt(request.UpdatedAt).
		RequireStatusEqual(schema.ServiceRequestStatus("in_repair"), "state.conflict").
		RequireAssignedUserIDEqual(assigned, "authorization.forbidden").
		SetQuoteAmount(schema.ServiceRequestQuoteAmount(formatMoney(quoteCents))).
		SetCompletedAt(input.CompletedAt).
		SetStatus(schema.ServiceRequestStatus("completed"))
	updated, err := caps.ServiceRequest.ConditionalUpdate(ctx, requestMutation)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}

	return capabilities.CompleteRepairOutput{
		FeeLedgerID:     ledger.ID,
		ServiceRequestID: updated.ID,
		UsageCount:      int64(len(createdUsages)),
	}, nil
}
