package fieldservice

import (
	"context"
	capabilities "example.com/m2-fieldservice/generated/capabilities"
	"example.com/m2-fieldservice/generated/data"
	"example.com/m2-fieldservice/generated/schema"
)

// DispatchServiceRequest implements the project-owned service_request.dispatch_service_request Handler.
func DispatchServiceRequest(ctx context.Context, caps capabilities.DispatchServiceRequestCapabilities, input capabilities.DispatchServiceRequestInput) (capabilities.DispatchServiceRequestOutput, error) {
	if input.AssignedUserID == "" || input.OrganizationUnitID == "" || input.RequestID == "" {
		return capabilities.DispatchServiceRequestOutput{}, reject("validation.invalid_request")
	}

	targetID := caps.Execution.TargetID()
	request, err := caps.ServiceRequest.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.DispatchServiceRequestOutput{}, err
	}

	assigned := schema.NewServiceRequestAssignedUserIDReference(schema.IdentityUserID(input.AssignedUserID))
	station := schema.NewServiceRequestOrganizationUnitIDReference(schema.IdentityOrganizationUnitID(input.OrganizationUnitID))
	mutation := data.NewServiceRequestUpdate(targetID).
		WithExpectedUpdatedAt(request.UpdatedAt).
		RequireStatusEqual(schema.ServiceRequestStatus("submitted"), "state.conflict").
		RequireAssignedUserIDNull("state.conflict").
		SetAssignedUserID(assigned).
		SetOrganizationUnitID(station).
		SetDispatchedAt(input.DispatchedAt).
		SetStatus(schema.ServiceRequestStatusDispatched)
	updated, err := caps.ServiceRequest.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.DispatchServiceRequestOutput{}, err
	}

	_, err = caps.Notifications.Dispatch(ctx, capabilities.DispatchServiceRequestNotificationIntent{
		EventType:        "service_request.assigned",
		SourceEventID:    input.RequestID,
		RecipientUserIDs: []string{input.AssignedUserID},
		Surface:          "business_workspace",
		SubjectObjectKey: "service_request",
		SubjectRecordID:  string(updated.ID),
		SubjectVersion:   updated.UpdatedAt,
		DedupeKey:        "service_request.assigned:" + input.RequestID,
		GroupKey:         "service_request:" + string(updated.ID),
		Alert:            true,
		OccurredAt:       input.DispatchedAt,
	})
	if err != nil {
		return capabilities.DispatchServiceRequestOutput{}, err
	}

	return capabilities.DispatchServiceRequestOutput{
		ServiceRequestID: updated.ID,
		Status:           schema.ServiceRequestDispatchServiceRequestStatusDispatched,
	}, nil
}
