package fieldservice

import (
	"context"

	capabilities "example.com/m2-fieldservice/generated/capabilities"
	"example.com/m2-fieldservice/generated/data"
	"example.com/m2-fieldservice/generated/schema"
)

// RequestWarrantyWaiver implements the project-owned service_request.request_warranty_waiver Handler.
func RequestWarrantyWaiver(ctx context.Context, caps capabilities.RequestWarrantyWaiverCapabilities, input capabilities.RequestWarrantyWaiverInput) (capabilities.RequestWarrantyWaiverOutput, error) {
	principal := caps.Execution.Principal()
	amountCents, amountValid := parseMoney(string(input.RequestedAmount))
	if !principal.Known || principal.UserID == "" || input.RequestID == "" || !input.WarrantyAsserted || !amountValid || amountCents <= 0 {
		return capabilities.RequestWarrantyWaiverOutput{}, reject("waiver.invalid_amount")
	}

	targetID := caps.Execution.TargetID()
	request, err := caps.ServiceRequest.Get(ctx, targetID)
	if err != nil {
		return capabilities.RequestWarrantyWaiverOutput{}, err
	}
	if request.Status != schema.ServiceRequestStatus("completed") {
		return capabilities.RequestWarrantyWaiverOutput{}, reject("state.conflict")
	}
	if request.AssignedUserID == nil || request.AssignedUserID.ID() != schema.IdentityUserID(principal.UserID) {
		return capabilities.RequestWarrantyWaiverOutput{}, reject("authorization.forbidden")
	}
	if request.QuoteAmount == nil {
		return capabilities.RequestWarrantyWaiverOutput{}, reject("waiver.invalid_amount")
	}
	quoteCents, quoteValid := parseMoney(string(*request.QuoteAmount))
	if !quoteValid || amountCents > quoteCents {
		return capabilities.RequestWarrantyWaiverOutput{}, reject("waiver.invalid_amount")
	}

	requestReference := schema.NewWarrantyWaiverServiceRequestIDReference(targetID)
	exists, err := caps.WarrantyWaiver.Exists(ctx, data.NewWarrantyWaiverQuery().WhereServiceRequestIDEqual(requestReference))
	if err != nil {
		return capabilities.RequestWarrantyWaiverOutput{}, err
	}
	if exists {
		return capabilities.RequestWarrantyWaiverOutput{}, reject("state.conflict")
	}

	status := schema.WarrantyWaiverStatus("pending")
	outputStatus := schema.ServiceRequestRequestWarrantyWaiverStatusPending
	waiverInput := schema.CreateWarrantyWaiver{
		CalculationTrace:     "requested_amount=" + formatMoney(amountCents) + ";threshold=500.00",
		OwnerDepartmentID:    request.OwnerDepartmentID,
		OwnerDepartmentPath:  request.OwnerDepartmentPath,
		PolicySnapshot:       `{"direct_apply_below":"500.00","version":1}`,
		RequestedAmount:      schema.WarrantyWaiverRequestedAmount(formatMoney(amountCents)),
		RequestedAt:          input.RequestedAt,
		RequesterUserID:      &principal.UserID,
		ServiceRequestID:     requestReference,
		Status:               status,
		ThresholdSnapshot:    schema.WarrantyWaiverThresholdSnapshot("500.00"),
		WarrantyAsserted:     true,
	}
	if amountCents < 50000 {
		waiverInput.Status = schema.WarrantyWaiverStatus("applied")
		waiverInput.DecidedAt = &input.RequestedAt
		outputStatus = schema.ServiceRequestRequestWarrantyWaiverStatusApplied
	}

	waiver, err := caps.WarrantyWaiver.Create(ctx, waiverInput)
	if err != nil {
		return capabilities.RequestWarrantyWaiverOutput{}, err
	}

	if amountCents < 50000 {
		waiverReference := schema.NewFeeLedgerWarrantyWaiverIDReference(waiver.ID)
		if _, err = caps.FeeLedger.Create(ctx, schema.CreateFeeLedger{
			Amount:             schema.FeeLedgerAmount(formatMoney(amountCents)),
			CalculationTrace:   "applied_waiver=requested_amount",
			InputSnapshot:      `{"threshold":"500.00","decision":"direct_apply"}`,
			Kind:               schema.FeeLedgerKind("waiver"),
			LineageKey:         "warranty_waiver:" + string(waiver.ID),
			OccurredAt:         input.RequestedAt,
			PolicySnapshot:     waiver.PolicySnapshot,
			ServiceRequestID: schema.NewFeeLedgerServiceRequestIDReference(targetID),
			WarrantyWaiverID: &waiverReference,
		}); err != nil {
			return capabilities.RequestWarrantyWaiverOutput{}, err
		}
		if _, err = caps.Notifications.Dispatch(ctx, capabilities.RequestWarrantyWaiverNotificationIntent{
			EventType:        "warranty_waiver.resolved",
			SourceEventID:    input.RequestID,
			RecipientUserIDs: []string{principal.UserID},
			Surface:          "business_workspace",
			SubjectObjectKey: "warranty_waiver",
			SubjectRecordID:  string(waiver.ID),
			SubjectVersion:   waiver.UpdatedAt,
			DedupeKey:        "warranty_waiver.resolved:" + string(waiver.ID),
			GroupKey:         "service_request:" + string(targetID),
			Alert:            true,
			OccurredAt:       input.RequestedAt,
		}); err != nil {
			return capabilities.RequestWarrantyWaiverOutput{}, err
		}
	}

	return capabilities.RequestWarrantyWaiverOutput{
		Status:            outputStatus,
		WarrantyWaiverID: waiver.ID,
	}, nil
}
