package fieldservice

import (
	"context"
	"time"

	capabilities "example.com/m2-fieldservice/generated/capabilities"
	"example.com/m2-fieldservice/generated/data"
	"example.com/m2-fieldservice/generated/schema"
)

// SendOverdueReminder implements the project-owned service_request.send_overdue_reminder Handler.
func SendOverdueReminder(ctx context.Context, caps capabilities.SendOverdueReminderCapabilities, input capabilities.SendOverdueReminderInput) (capabilities.SendOverdueReminderOutput, error) {
	location, err := time.LoadLocation("Asia/Shanghai")
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	scheduledAt := input.ScheduledAt.In(location)
	if scheduledAt.Weekday() == time.Saturday || scheduledAt.Weekday() == time.Sunday {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}

	targetID := caps.Execution.TargetID()
	request, err := caps.ServiceRequest.Get(ctx, targetID)
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	if request.Status != schema.ServiceRequestStatus("dispatched") || request.DispatchedAt == nil || request.AssignedUserID == nil {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}
	if !request.DispatchedAt.Before(input.ScheduledAt.Add(-48 * time.Hour)) {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}

	businessDate := time.Date(scheduledAt.Year(), scheduledAt.Month(), scheduledAt.Day(), 0, 0, 0, 0, location)
	dedupeKey := string(targetID) + ":" + businessDate.Format("2006-01-02")
	exists, err := caps.OverdueReminder.Exists(ctx, data.NewOverdueReminderQuery().WhereDedupeKeyEqual(dedupeKey))
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	if exists {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}

